snippet_css:
:root{
  --bg: #FFFFFF;
  --fg: #111111;
  --muted: #616161;
  --surface: #FFFFFF;
  --border: #E4E4E4;
  --accent: #0B57D0;
  --accent-fg: #FFFFFF;
  --radius: 10px;
  --radius-sm: 6px;
  --shadow: none;
  --btn-shadow: none;
  --art-bg: #F5F5F5;
  --media-bg: #F7F7F7;
  --cta-bg: #F7F7F7;
  --input-bg: #FFFFFF;
  --ok: #0E6B3E;
  --warn: #B3261E;
  --font-display: Inter,'Noto Sans TC',sans-serif;
  --font-body: Inter,'Noto Sans TC',sans-serif;
  --font-mono: ui-monospace,Menlo,monospace;
  --focus-ring: var(--accent);
}

snippet_tailwind:
// tailwind.config.js → theme.extend
{
  "colors": {
    "bg": "#FFFFFF",
    "fg": "#111111",
    "muted": "#616161",
    "surface": "#FFFFFF",
    "border": "#E4E4E4",
    "accent": "#0B57D0",
    "accent-fg": "#FFFFFF",
    "ok": "#0E6B3E",
    "warn": "#B3261E",
    "focus-ring": "var(--accent)"
  },
  "borderRadius": {
    "DEFAULT": "6px",
    "lg": "10px"
  },
  "fontFamily": {
    "display": [
      "Inter,'Noto Sans TC',sans-serif"
    ],
    "body": [
      "Inter,'Noto Sans TC',sans-serif"
    ]
  }
}
